import React, { Component } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Button } from 'reactstrap';


class App extends Component {
  constructor(props) {
    super(props);
    this.state = {
      colores: ["primary", "secondary", "secondary"]
    }
  }

  cambiar(p) {
    let col = ["secondary", "secondary", "secondary"];
    col[p] = "primary"
    this.setState({ colores: col })
  }

  render() {
    return (
      <div className="App">
        <Botonaco pos={0} color={this.state.colores[0]} clicar={(p)=>this.cambiar(p)}/>
        <Botonaco pos={1} color={this.state.colores[1]} clicar={(p)=>this.cambiar(p)}/>
        <Botonaco pos={2} color={this.state.colores[2]} clicar={(p)=>this.cambiar(p)}/>
      </div>
    );
  }
}

const Botonaco = (props) => {
  return (
    <>
      <Button color={props.color} onClick={()=>props.clicar(props.pos)} />
    </>
  )
}


export default App;
